    title: input.title,
    roomId: input.roomId,
    date: input.date,
    startMin: input.startMin,
    endMin: input.endMin,
    bookedBy: input.bookedBy,
    attendeeCount: input.attendeeCount
  };
  return { ok: true, appointment: appointment, conflict: null, message: 'valid', field: '' };
}
